            if (!state.ifaces.length) { toast('\u8FD8\u6CA1\u6709\u63A5\u53E3'); return; }
            toast('\u6B63\u5728\u62C9\u53D6\u5168\u90E8\u63A5\u53E3\u2026');
            try {
                var r = await api('/js/interfaces/fetch', { method: 'POST' });
                toast(r.message || '\u5B8C\u6210');
                await loadIfaces();
                await load();
            } catch (e) { toast('\u62C9\u53D6\u5931\u8D25\uFF1A' + e.message); }
