            if (!(await askConfirm('\u6E05\u7A7A\u63A5\u53E3\u5217\u8868', '\u5DF2\u5B89\u88C5\u7684\u6E90\u6587\u4EF6\u4F1A\u4FDD\u7559\uFF0C\u786E\u5B9A\u6E05\u7A7A\u63A5\u53E3\u8BB0\u5F55\uFF1F'))) return;
